package com.rationportal.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; @Entity @Table(name="distribution_logs") public class DistributionLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="ration_card_id") private RationCard rationCard; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="member_id") private FamilyMember member; @Column(name="quantity_kg", nullable=false) private BigDecimal quantityKg; @Column(name="distribution_date", nullable=false) private LocalDate distributionDate; @Column(name="fps_id") private String fpsId; @Column(name="transaction_status", nullable=false) private String transactionStatus; public Long getId(){return id;} public RationCard getRationCard(){return rationCard;} public void setRationCard(RationCard rationCard){this.rationCard=rationCard;} public FamilyMember getMember(){return member;} public void setMember(FamilyMember member){this.member=member;} public BigDecimal getQuantityKg(){return quantityKg;} public void setQuantityKg(BigDecimal quantityKg){this.quantityKg=quantityKg;} public LocalDate getDistributionDate(){return distributionDate;} public void setDistributionDate(LocalDate distributionDate){this.distributionDate=distributionDate;} public String getFpsId(){return fpsId;} public void setFpsId(String fpsId){this.fpsId=fpsId;} public String getTransactionStatus(){return transactionStatus;} public void setTransactionStatus(String transactionStatus){this.transactionStatus=transactionStatus;} }
